  /*Definition: librarian scans a user ID and a book barcode to process a borrowing request.
   *Precondition: The system first checks whether the user exists, is not suspended, and still has borrowing quota.
   *Postcondition:Then it confirms the selected copy is available (or reserved for this same user), creates a new loan record, sets the due date by user type, updates book status to loaned, and returns true when the checkout succeeds.*/
  borrowBook(uid: string, barcode: string): boolean {
    /*Definition Start*/
    let user: User = l({
      logic: () =>
        getRepository(User).find(
          (u: any) =>
            l({
              logic: () => u.UserID === uid,
              description: "u.UserID=uid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(u|u.UserID=uid)",
    }).build().pass;
    let bookCopy: BookCopy = l({
      logic: () =>
        getRepository(BookCopy).find(
          (c: any) =>
            l({
              logic: () => c.Barcode === barcode,
              description: "c.Barcode=barcode",
            }).build().pass,
        ),
      description: "BookCopy.allInstance()->any(c|c.Barcode=barcode)",
    }).build().pass;
    let activeLoans: Loan[] = l({
      logic: () =>
        user.LoanedBook.filter(
          (_l: any) =>
            l({
              logic: () => _l.IsReturned === false,
              description: "l.IsReturned=false",
            }).build().pass,
        ),
      description: "user.LoanedBook->select(l|l.IsReturned=false)",
    }).build().pass;
    let reservation: Reserve[] = l({
      logic: () =>
        bookCopy.ReservationRecord.filter(
          (r: any) =>
            l({
              logic: () => r.IsReserveClosed === false,
              description: "r.IsReserveClosed=false",
            }).build().pass,
        ),
      description:
        "bookCopy.ReservationRecord->select(r|r.IsReserveClosed=false)",
    }).build().pass;
    let reserve: Reserve = l({
      logic: () =>
        bookCopy.ReservationRecord.find(
          (r: any) =>
            l({
              logic: () => r.IsReserveClosed === false,
              description: "r.IsReserveClosed=false",
            }).build().pass,
        ),
      description: "bookCopy.ReservationRecord->any(r|r.IsReserveClosed=false)",
    }).build().pass;
    let newLoanDueDate: dayjs.Dayjs = l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsTypeOf(user, Student),
            description: "user.oclIsTypeOf(Student)",
          }),
        description: "user.oclIsTypeOf(Student)",
        then: l({
          logic: () => this.studentLoanPeriod,
          description: "self.studentLoanPeriod",
        }),
        else: l({
          logic: () => this.facultyLoanPeriod,
          description: "self.facultyLoanPeriod",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
