        logic: () => StandardOPs.oclIsUndefined(user) === false,
        description: "user.oclIsUndefined()=false",
      })
        .and({
          logic: () => user.BorrowStatus === BorrowStatus.NORMAL,
          description: "user.BorrowStatus=BorrowStatus::NORMAL",
        })
        .and({
          logic: () => activeLoans.length < this.maxBorrowLimit,
          description: "activeLoans.size()<self.maxBorrowLimit",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(bookCopy) === false,
          description: "bookCopy.oclIsUndefined()=false",
        })
        .and({
          logic: () =>
            l({
              logic: () => bookCopy.Status === CopyStatus.AVAILABLE,
              description: "bookCopy.Status=CopyStatus::AVAILABLE",
            }).or({
              logic: () => reserve.ReservedUser === user,
              description: "reserve.ReservedUser=user",
            }),
          description:
            "(bookCopy.Status=CopyStatus::AVAILABLEorreserve.ReservedUser=user)",
        })
        .build();
    if (!isPreconditionPass) {
