      })
      .and({
        execute: () => (loan.LoanedUser = user),
        description: "loan.LoanedUser=user",
      })
      .and({
        execute: () => (loan.LoanedCopy = bookCopy),
        description: "loan.LoanedCopy=bookCopy",
      })
      .and({
        execute: () => (loan.LoanDate = this.currentDate),
        description: "loan.LoanDate=self.currentDate",
      })
      .and({
