  borrowBook(uid: string, barcode: string): boolean {
    /*Definition Start*/
    let user: User = l({
      logic: () =>
        getRepository(User).find(
          (u: any) =>
            l({
              logic: () => u.UserID === uid,
              description: "u.UserID=uid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(u|u.UserID=uid)",
    }).build().pass;
    let bookCopy: BookCopy = l({
      logic: () =>
        getRepository(BookCopy).find(
          (c: any) =>
            l({
              logic: () => c.Barcode === barcode,
              description: "c.Barcode=barcode",
            }).build().pass,
        ),
      description: "BookCopy.allInstance()->any(c|c.Barcode=barcode)",
    }).build().pass;
    let activeLoans: Loan[] = l({
      logic: () =>
        user.LoanedBook.filter(
          (_l: any) =>
            l({
              logic: () => _l.IsReturned === false,
              description: "l.IsReturned=false",
            }).build().pass,
        ),
      description: "user.LoanedBook->select(l|l.IsReturned=false)",
    }).build().pass;
    let reserve: Reserve = l({
      logic: () =>
        bookCopy.ReservationRecord.find(
          (r: any) =>
            l({
              logic: () => r.IsReserveClosed === false,
              description: "r.IsReserveClosed=false",
            }).build().pass,
        ),
      description: "bookCopy.ReservationRecord->any(r|r.IsReserveClosed=false)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(user) === false,
        description: "user.oclIsUndefined()=false",
      })
        .and({
          logic: () => user.BorrowStatus === BorrowStatus.NORMAL,
          description: "user.BorrowStatus=BorrowStatus::NORMAL",
        })
        .and({
          logic: () => activeLoans.length < 5,
          description: "activeLoans.size()<5",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(bookCopy) === false,
          description: "bookCopy.oclIsUndefined()=false",
        })
        .and({
          logic: () =>
            l({
              logic: () => bookCopy.Status === CopyStatus.AVAILABLE,
              description: "bookCopy.Status=CopyStatus::AVAILABLE",
            }).or({
              logic: () => reserve.ReservedUser === user,
              description: "reserve.ReservedUser=user",
            }),
          description:
            "(bookCopy.Status=CopyStatus::AVAILABLEorreserve.ReservedUser=user)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

